return items.map(item => {
  const j = item.json;
  const title = j.title || '';
  const summary = j.contentSnippet || j.content || j.description || '';
  const text = `${title} ${summary}`.toLowerCase();
  const publishedRaw = j.isoDate || j.pubDate || j.pubdate || '';
  const publishedAt = publishedRaw ? new Date(publishedRaw) : null;
  const publishedTs = publishedAt && !Number.isNaN(publishedAt.getTime()) ? publishedAt.getTime() : null;
  const ageHours = publishedTs ? (Date.now() - publishedTs) / 3600000 : 9999;
  const critical = ['tariff', 'tariffs', 'duties', 'section 301', 'section 232', 'executive order', 'proclamation', 'retaliation', 'trade war', 'trade dispute'];
  const countries = ['china', 'mexico', 'canada', 'european union', 'eu', 'japan', 'south korea', 'taiwan', 'brazil', 'india'];
  const channels = ['semiconductor', 'chips', 'autos', 'steel', 'aluminum', 'copper', 'oil', 'rare earths', 'supply chain', 'exports', 'imports'];
  const hardImpact = ['immediately', 'effective', 'ban', 'restriction', 'sanction', 'sanctions', 'emergency', 'investigation', 'review', 'proclamation', 'executive order'];
  const soft = ['considering', 'may', 'could', 'proposal', 'discussion', 'rumor', 'sources say', 'draft'];
  const layerWeight = Number(j.weight || 0);
  const count = arr => arr.filter(term => text.includes(term)).length;
  const criticalHits = count(critical);
  const countryHits = count(countries);
  const channelHits = count(channels);
  const hardImpactHits = count(hardImpact);
  const softHits = count(soft);
  let score = layerWeight;
  score += Math.min(criticalHits, 3) * 34;
  score += Math.min(countryHits, 2) * 22;
  score += Math.min(channelHits, 2) * 16;
  score += Math.min(hardImpactHits, 2) * 16;
  if (criticalHits >= 1 && countryHits >= 1) score += 20;
  if (criticalHits >= 1 && channelHits >= 1) score += 16;
  if (/white house|ustr|federal register|treasury|ofac|reuters|ap news|bloomberg/.test(text)) score += 10;
  score -= Math.min(softHits, 2) * 22;
  let recencyBoost = 0;
  if (ageHours <= 0.5) recencyBoost = 45;
  else if (ageHours <= 1) recencyBoost = 35;
  else if (ageHours <= 2) recencyBoost = 28;
  else if (ageHours <= 4) recencyBoost = 20;
  else if (ageHours <= 8) recencyBoost = 12;
  else if (ageHours <= 16) recencyBoost = 6;
  else if (ageHours <= 24) recencyBoost = 0;
  else if (ageHours <= 48) recencyBoost = -15;
  else recencyBoost = -100;
  score += recencyBoost;
  score = Math.max(0, Math.min(220, score));
  let alertLevel = 'GREEN';
  if (score >= 155) alertLevel = 'RED';
  else if (score >= 125) alertLevel = 'ORANGE';
  else if (score >= 100) alertLevel = 'YELLOW';
  return { json: { ...j, normalizedTitle: title.trim(), summary: summary.trim(), publishedTs, ageHours: Math.round(ageHours * 10) / 10, recencyBoost, preScore: score, preAlertLevel: alertLevel } };
});

const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};
const now = Date.now();
const ttlMs = 60 * 60 * 1000;
const candidates = [];
for (const item of items) {
  const j = item.json;
  const title = (j.normalizedTitle || j.title || '').toLowerCase().trim();
  const link = (j.link || '').trim();
  const key = `${title}|${link}`;
  const text = `${j.normalizedTitle || ''} ${j.summary || ''}`;
  const isRecentEnough = typeof j.publishedTs === 'number' && now - j.publishedTs <= 48 * 60 * 60 * 1000;
  const strongEnough = j.preScore >= 100;
  const notSoft = !/\b(rumor|draft|sources say)\b/i.test(text);
  if (isRecentEnough && strongEnough && notSoft) {
    const seenAt = staticData.seen[key];
    if (!seenAt || now - seenAt > ttlMs) {
      candidates.push({ item, key });
    }
  }
}
for (const [key, ts] of Object.entries(staticData.seen)) {
  if (now - ts > ttlMs) delete staticData.seen[key];
}
if (!candidates.length) return [];
candidates.sort((a, b) => {
  const scoreDiff = (b.item.json.preScore || 0) - (a.item.json.preScore || 0);
  if (scoreDiff !== 0) return scoreDiff;
  return (a.item.json.ageHours || 9999) - (b.item.json.ageHours || 9999);
});
const winner = candidates[0];
staticData.seen[winner.key] = now;
const text = `${winner.item.json.normalizedTitle || ''} ${winner.item.json.summary || ''}`.toLowerCase();
const relief = /\b(exemption|delay|pause|relief|reduce|rollback|suspend|waiver)\b/.test(text);
if (winner.item.json.preAlertLevel === 'RED') {
  winner.item.json.tendency = relief ? 'alta ou alivio de baixa' : 'baixa forte';
  winner.item.json.conviction = 'alta';
} else if (winner.item.json.preAlertLevel === 'ORANGE') {
  winner.item.json.tendency = relief ? 'alta moderada' : 'baixa moderada';
  winner.item.json.conviction = 'media';
} else {
  winner.item.json.tendency = relief ? 'leve alivio' : 'baixa leve ou monitoramento';
  winner.item.json.conviction = 'baixa';
}
winner.item.json.winRead = relief ? 'WIN pode aliviar se dolar cair e indice ficar acima da VWAP.' : winner.item.json.preAlertLevel === 'RED' ? 'WIN tende a sofrer pressao vendedora se dolar subir e perder VWAP/minima da abertura.' : winner.item.json.preAlertLevel === 'ORANGE' ? 'WIN pode sentir pressao se o dolar confirmar alta e o indice perder VWAP.' : 'WIN ainda pede confirmacao de fluxo antes de venda agressiva.';
winner.item.json.dollarRead = relief ? 'Dolar pode ceder se o mercado ler como reducao de risco comercial.' : winner.item.json.preAlertLevel === 'RED' ? 'Dolar tende a ganhar forca em leitura risk-off ou medo de tarifa.' : winner.item.json.preAlertLevel === 'ORANGE' ? 'Dolar pode ganhar tracao se a noticia contaminar risco global.' : 'Dolar pode oscilar, mas precisa de confirmacao de fluxo.';
winner.item.json.nasdaqEsRead = relief ? 'Nasdaq/ES podem reagir melhor se a noticia reduzir risco de inflacao/tarifas.' : winner.item.json.preAlertLevel === 'RED' ? 'Nasdaq/ES tendem a ficar pressionados se a noticia elevar risco de inflacao, juros ou guerra comercial.' : winner.item.json.preAlertLevel === 'ORANGE' ? 'Nasdaq/ES podem sentir pressao moderada se o mercado ampliar leitura de risco.' : 'Nasdaq/ES entram mais como contexto do que gatilho.';
winner.item.json.reason = winner.item.json.preAlertLevel === 'RED' ? (relief ? 'Alivio relevante em tema de tarifa/comercio.' : 'Noticia forte com potencial claro de impacto macro e risco.') : winner.item.json.preAlertLevel === 'ORANGE' ? (relief ? 'Alivio parcial em tema comercial importante.' : 'Noticia relevante com potencial de impacto moderado.') : 'Ruido util para monitoramento e contexto operacional.';
return [winner.item];
